1	export type Cell = [x: number, y: number];
2	
3	function isSameCell([x, y]: Cell, [otherX, otherY]: Cell): boolean {
4	  return x === otherX && y === otherY;
5	}
6	
7	function isNeighbourOf(cell: Cell, candidate: Cell): boolean {
8	  const [x, y] = cell;
9	  const [candidateX, candidateY] = candidate;
10	  const isWithinOneStep =
11	    Math.abs(candidateX - x) <= 1 && Math.abs(candidateY - y) <= 1;
12	  return isWithinOneStep && !isSameCell(cell, candidate);
13	}
14	
15	function countNeighbours(cell: Cell, liveCells: Cell[]): number {
16	  return liveCells.filter((candidate) => isNeighbourOf(cell, candidate)).length;
17	}
18	
19	const NEIGHBOUR_OFFSETS: Cell[] = [
20	  [-1, -1],
21	  [-1, 0],
22	  [-1, 1],
23	  [0, -1],
24	  [0, 1],
25	  [1, -1],
26	  [1, 0],
27	  [1, 1],
28	];
29	
30	function neighboursOf([x, y]: Cell): Cell[] {
31	  return NEIGHBOUR_OFFSETS.map(([dx, dy]): Cell => [x + dx, y + dy]);
32	}
33	
34	function isAlive(cell: Cell, liveCells: Cell[]): boolean {
35	  return liveCells.some((live) => isSameCell(live, cell));
36	}
37	
38	/**
39	 * Every cell that could possibly be alive next generation: the live cells
40	 * themselves, plus their neighbours. Cells further away have no live
41	 * neighbours, so they stay dead.
42	 */
43	function candidateCells(liveCells: Cell[]): Cell[] {
44	  const candidates = new Map<string, Cell>();
45	  for (const cell of [...liveCells, ...liveCells.flatMap(neighboursOf)]) {
46	    candidates.set(`${cell[0]},${cell[1]}`, cell);
47	  }
48	  return [...candidates.values()];
49	}
50	
51	function isAliveNextGeneration(cell: Cell, liveCells: Cell[]): boolean {
52	  const neighbours = countNeighbours(cell, liveCells);
53	  return neighbours === 3 || (neighbours === 2 && isAlive(cell, liveCells));
54	}
55	
56	export function nextGeneration(liveCells: Cell[]): Cell[] {
57	  return candidateCells(liveCells).filter((cell) =>
58	    isAliveNextGeneration(cell, liveCells),
59	  );
60	}
